public class EinvoiceRepository
{
private readonly IDbConnection _connection;
private readonly IDbTransaction _transaction;
public EinvoiceRepository(IDbConnection connection, IDbTransaction transaction)
{
_connection = connection ?? throw new ArgumentNullException(nameof(connection));
_transaction = transaction;
}
public void UpdateFromDraftInvoiceSavedEvent(DraftInvoiceEvent draftEvent)
{
if (draftEvent == null)
throw new ArgumentNullException(nameof(draftEvent), "Data draft invoice tidak boleh null.");
if (draftEvent.Invoice == null)
throw new InvalidOperationException("Invoice object belum terisi.");
if (string.IsNullOrWhiteSpace(draftEvent.Invoice.InvoiceNumber))
throw new InvalidOperationException("Nomor invoice belum diisi.");
try
{
string sql = @"UPDATE tbl_invoice
SET customer_name = @CustomerName,
total_amount = @TotalAmount,
updated_at = GETDATE()
WHERE invoice_number = @InvoiceNumber";
_connection.Execute(sql, new
{
CustomerName = draftEvent.Invoice.CustomerName ?? "(Tidak ada nama)",
TotalAmount = draftEvent.Invoice.TotalAmount,
InvoiceNumber = draftEvent.Invoice.InvoiceNumber
}, _transaction);
}
catch (Exception ex)
{
// Logging kesalahan untuk memudahkan debugging
Console.Error.WriteLine($"[ERROR] Gagal update draft invoice: {ex.Message}");
throw;
}
}
}
